use vstd::prelude::*;

verus! {

fn max_of_list(lst: Vec<i32>) -> (result: i32)
    requires
        lst.len() > 0,
    ensures
        // result is some element from the list
        exists|i: usize| i < lst.len() && result == lst[i],
    ensures
        // result is >= all elements
        forall|i: usize| i < lst.len() ==> lst[i] <= result,
{
    // Start with the first element as max
    let mut max_val: i32 = lst[0];
    let mut idx: usize = 1;

    while idx < lst.len()
        invariant
            idx <= lst.len(),
            // max_val equals max element in lst[..idx]
            // (helps verify correctness)
            forall|j: usize| j < idx ==> lst[j] <= max_val,
            exists|j: usize| j < idx && lst[j] == max_val,
        decreases lst.len() - idx,
    {
        if lst[idx] > max_val {
            max_val = lst[idx];
        }
        idx = idx + 1;
    }

    max_val
}

}
